PRAGMA foreign_keys=ON;
CREATE TABLE dim_unidade(id_unidade INTEGER PRIMARY KEY,unidade TEXT NOT NULL,cidade TEXT NOT NULL,uf TEXT NOT NULL,regiao TEXT NOT NULL);
CREATE TABLE dim_setor(id_setor INTEGER PRIMARY KEY,id_unidade INTEGER NOT NULL REFERENCES dim_unidade(id_unidade),setor TEXT NOT NULL,centro_custo TEXT NOT NULL);
CREATE TABLE dim_linha(id_linha INTEGER PRIMARY KEY,id_setor INTEGER NOT NULL REFERENCES dim_setor(id_setor),linha TEXT NOT NULL,capacidade_hora INTEGER NOT NULL,criticidade TEXT NOT NULL);
CREATE TABLE dim_equipamento(id_equipamento INTEGER PRIMARY KEY,codigo TEXT NOT NULL UNIQUE,equipamento TEXT NOT NULL,categoria TEXT NOT NULL,fabricante TEXT NOT NULL,modelo TEXT NOT NULL,id_unidade INTEGER NOT NULL REFERENCES dim_unidade(id_unidade),id_setor INTEGER NOT NULL REFERENCES dim_setor(id_setor),id_linha INTEGER REFERENCES dim_linha(id_linha),criticidade TEXT NOT NULL,data_instalacao DATE NOT NULL,status_equipamento TEXT NOT NULL,valor_aquisicao NUMERIC NOT NULL);
CREATE TABLE dim_tipo_manutencao(id_tipo_manutencao INTEGER PRIMARY KEY,tipo_manutencao TEXT NOT NULL,classificacao TEXT NOT NULL,planejada INTEGER NOT NULL,exige_parada INTEGER NOT NULL);
CREATE TABLE plano_preventivo(id_plano INTEGER PRIMARY KEY,id_equipamento INTEGER NOT NULL REFERENCES dim_equipamento(id_equipamento),nome_plano TEXT NOT NULL,periodicidade_dias INTEGER NOT NULL,tempo_estimado_horas NUMERIC NOT NULL,data_ultima_execucao DATE,data_proxima_execucao DATE NOT NULL,status_plano TEXT NOT NULL);
CREATE TABLE ordem_servico(id_os INTEGER PRIMARY KEY,numero_os TEXT NOT NULL UNIQUE,id_equipamento INTEGER NOT NULL REFERENCES dim_equipamento(id_equipamento),id_tipo_manutencao INTEGER NOT NULL REFERENCES dim_tipo_manutencao(id_tipo_manutencao),id_plano INTEGER REFERENCES plano_preventivo(id_plano),data_abertura DATETIME NOT NULL,data_programada DATETIME,data_inicio DATETIME,data_conclusao DATETIME,prioridade TEXT NOT NULL,status_os TEXT NOT NULL,descricao_problema TEXT NOT NULL,causa_identificada TEXT,solucao_aplicada TEXT,retrabalho INTEGER NOT NULL,custo_mao_obra NUMERIC NOT NULL DEFAULT 0,custo_pecas NUMERIC NOT NULL DEFAULT 0,custo_terceiros NUMERIC NOT NULL DEFAULT 0);
CREATE TABLE fato_falha(id_falha INTEGER PRIMARY KEY,id_equipamento INTEGER NOT NULL REFERENCES dim_equipamento(id_equipamento),id_os INTEGER NOT NULL REFERENCES ordem_servico(id_os),data_falha DATETIME NOT NULL,componente TEXT NOT NULL,modo_falha TEXT NOT NULL,causa_raiz TEXT,severidade TEXT NOT NULL,recorrente INTEGER NOT NULL,impacto_producao INTEGER NOT NULL);
CREATE TABLE fato_parada(id_parada INTEGER PRIMARY KEY,id_equipamento INTEGER NOT NULL REFERENCES dim_equipamento(id_equipamento),id_os INTEGER REFERENCES ordem_servico(id_os),data_inicio DATETIME NOT NULL,data_fim DATETIME NOT NULL,duracao_minutos INTEGER NOT NULL,planejada INTEGER NOT NULL,motivo TEXT NOT NULL,quantidade_nao_produzida INTEGER NOT NULL,custo_estimado NUMERIC NOT NULL,turno TEXT NOT NULL);
CREATE TABLE dim_colaborador(id_colaborador INTEGER PRIMARY KEY,matricula TEXT NOT NULL UNIQUE,nome_ficticio TEXT NOT NULL,especialidade TEXT NOT NULL,cargo TEXT NOT NULL,equipe TEXT NOT NULL,turno TEXT NOT NULL,id_unidade INTEGER NOT NULL REFERENCES dim_unidade(id_unidade),custo_hora NUMERIC NOT NULL,status_colaborador TEXT NOT NULL);
CREATE TABLE fato_apontamento(id_apontamento INTEGER PRIMARY KEY,id_os INTEGER NOT NULL REFERENCES ordem_servico(id_os),id_colaborador INTEGER NOT NULL REFERENCES dim_colaborador(id_colaborador),data_apontamento DATE NOT NULL,horas NUMERIC NOT NULL,tipo_hora TEXT NOT NULL,custo NUMERIC NOT NULL,atividade TEXT NOT NULL);
CREATE TABLE dim_peca(id_peca INTEGER PRIMARY KEY,codigo_peca TEXT NOT NULL UNIQUE,descricao TEXT NOT NULL,categoria TEXT NOT NULL,unidade_medida TEXT NOT NULL,custo_unitario NUMERIC NOT NULL,estoque_atual INTEGER NOT NULL,estoque_minimo INTEGER NOT NULL,ponto_reposicao INTEGER NOT NULL,item_critico INTEGER NOT NULL);
CREATE TABLE fato_consumo_peca(id_consumo INTEGER PRIMARY KEY,id_os INTEGER NOT NULL REFERENCES ordem_servico(id_os),id_peca INTEGER NOT NULL REFERENCES dim_peca(id_peca),data_consumo DATE NOT NULL,quantidade NUMERIC NOT NULL,custo_total NUMERIC NOT NULL);
CREATE TABLE dim_fornecedor(id_fornecedor INTEGER PRIMARY KEY,fornecedor_ficticio TEXT NOT NULL,categoria TEXT NOT NULL,uf TEXT NOT NULL,prazo_medio_dias INTEGER NOT NULL,avaliacao NUMERIC NOT NULL,status_fornecedor TEXT NOT NULL);
CREATE TABLE fato_servico_terceirizado(id_servico INTEGER PRIMARY KEY,id_os INTEGER NOT NULL REFERENCES ordem_servico(id_os),id_fornecedor INTEGER NOT NULL REFERENCES dim_fornecedor(id_fornecedor),tipo_servico TEXT NOT NULL,data_solicitacao DATE NOT NULL,data_conclusao DATE,custo_final NUMERIC NOT NULL,status_servico TEXT NOT NULL);
CREATE TABLE fato_producao(id_producao INTEGER PRIMARY KEY,data_referencia DATE NOT NULL,id_unidade INTEGER NOT NULL REFERENCES dim_unidade(id_unidade),id_setor INTEGER NOT NULL REFERENCES dim_setor(id_setor),id_linha INTEGER NOT NULL REFERENCES dim_linha(id_linha),quantidade_planejada INTEGER NOT NULL,quantidade_produzida INTEGER NOT NULL,quantidade_perdida INTEGER NOT NULL,horas_programadas NUMERIC NOT NULL,horas_disponiveis NUMERIC NOT NULL);
CREATE TABLE dim_calendario(data DATE PRIMARY KEY,dia INTEGER NOT NULL,mes INTEGER NOT NULL,nome_mes TEXT NOT NULL,trimestre INTEGER NOT NULL,ano INTEGER NOT NULL,semana_ano INTEGER NOT NULL,dia_semana TEXT NOT NULL,dia_util INTEGER NOT NULL);
CREATE INDEX idx_os_equipamento ON ordem_servico(id_equipamento); CREATE INDEX idx_os_abertura ON ordem_servico(data_abertura); CREATE INDEX idx_falha_equipamento ON fato_falha(id_equipamento); CREATE INDEX idx_parada_inicio ON fato_parada(data_inicio); CREATE INDEX idx_producao_data ON fato_producao(data_referencia);
CREATE VIEW vw_custo_os AS SELECT o.id_os,o.numero_os,e.codigo,e.equipamento,t.tipo_manutencao,o.status_os,ROUND(o.custo_mao_obra+o.custo_pecas+o.custo_terceiros,2) custo_total FROM ordem_servico o JOIN dim_equipamento e ON e.id_equipamento=o.id_equipamento JOIN dim_tipo_manutencao t ON t.id_tipo_manutencao=o.id_tipo_manutencao;
CREATE VIEW vw_confiabilidade AS SELECT e.id_equipamento,e.codigo,e.equipamento,COUNT(DISTINCT f.id_falha) falhas,COALESCE(SUM(p.duracao_minutos),0) minutos_parados,ROUND(AVG(p.duracao_minutos),1) mttr_minutos FROM dim_equipamento e LEFT JOIN fato_falha f ON f.id_equipamento=e.id_equipamento LEFT JOIN fato_parada p ON p.id_equipamento=e.id_equipamento GROUP BY e.id_equipamento;
